window.DOSIK=window.DOSIK||{};DOSIK["gs_law"]={"1":[{"t":"table","title":"관세법 용어","head":["용어","내용"],"rows":[["수입·수출·반송","반송은 국내에 도착한 외국물품이 수입통관절차를 거치지 아니하고 다시 외국으로 반출되는 것이다 · 수입통관을 마친 물품을 내보내는 것은 수출이다 · 선박용품·항공기용품·차량용품을 운송수단 안에서 그 용도에 따라 소비하거나 여행자가 휴대품을 운송수단 또는 관세통로에서 소비하는 것은 수입으로 보지 않는다"],["외국물품","수입신고 수리 전의 도착물품과 수출신고가 수리된 물품은 외국물품이다 · 외국 선박이 공해에서 포획한 수산물은 외국물품이고, 보수작업으로 외국물품에 부가된 내국물품도 외국물품으로 본다"],["내국물품","입항전수입신고가 수리된 물품, 수입신고수리전 반출승인을 받아 반출된 물품, 수입신고전 즉시반출신고를 하고 반출된 물품, 우리나라의 선박 등이 공해에서 포획한 수산물은 내국물품이다"],["운송수단·용품","국제무역선·국제무역기는 무역을 위하여 우리나라와 외국 간을 운항하고, 국내운항선·국내운항기는 국내에서만 운항한다 · 항공기용품·차량용품은 선박용품에 준하는 물품으로서 해당 항공기·차량에서만 사용되는 것이다"],["환적","동일한 세관의 관할구역에서 옮겨 싣는 것이 환적이고, 다른 세관의 관할구역으로 운송하여 옮겨 싣는 것이 복합환적이다"],["운영인","특허보세구역 설치·운영 특허를 받은 자와 종합보세사업장 설치·운영 신고를 한 자이고 지정장치장 화물관리인은 들어가지 않는다"],["탁송품","송달업자에게 위탁하여 반입하거나 반출하는 상업서류·견본품·자가사용물품 등이며, 물품을 휴대하여 반출입하는 것을 업으로 하는 자에게 맡긴 물품은 제외한다"],["관세조사","방문 또는 서면으로 장부·서류를 조사하는 것이고 통합조사도 포함한다"]]},{"t":"table","title":"법 적용 원칙과 기한","head":["구분","내용"],"rows":[["법 적용 원칙","신의성실은 납세자와 세관공무원 모두에게 적용된다 · 관세를 납부하여야 하는 물품에 대해서는 다른 조세·공과금·채권에 우선하여 관세를 징수한다 · 관세청장은 관세 조약의 해석에 의문이 있으면 재정경제부장관에게 해석을 요청하고, 재정경제부장관은 관련 국제기구에 질의할 수 있다"],["내국세등","세관장이 수입물품에 부과·징수하는 내국세등은 부가가치세, 지방소비세, 담배소비세, 지방교육세, 개별소비세, 주세, 교육세, 교통·에너지·환경세, 농어촌특별세다 · 소득세는 들어가지 않는다 · 이들 세법과 관세법이 상충하면 관세법을 우선 적용한다"],["기한","기한이 토요일·일요일, 공휴일·대체공휴일, 노동절이면 그 다음 날이 기한이고, 국가관세종합정보시스템 장애로 가동이 정지되면 장애가 복구된 날의 다음 날이 기한이다 · 천재지변 등으로 기한을 지킬 수 없으면 세관장은 1년을 넘지 아니하는 기간을 정하여 연장한다"],["공시송달","공고한 날부터 14일이 지나면 송달된 것으로 보며, 2회 이상 방문하고 첫 방문과 마지막 방문 사이가 3일 이상이어야 부재를 이유로 공시송달할 수 있다"]]},{"t":"table","title":"과세물건 확정의 시기","head":["물품","기준 시기"],"rows":[["일반 물품","관세는 수입신고를 하는 때의 물품의 성질과 그 수량에 따라 부과한다"],["즉시반출신고 물품","즉시반출신고를 한 때"],["우편물","통관우체국에 도착한 때"],["도난·분실물품","도난되거나 분실된 때"],["매각물품","매각된 때"],["보세운송기간 경과 물품","보세운송을 신고하거나 승인받은 때"],["장치물품 폐기","멸실되거나 폐기된 때"],["수리 전 소비·사용 물품","소비하거나 사용한 때"]]},{"t":"table","title":"납세의무자","head":["경우","납세의무자"],"rows":[["원칙","수입신고하는 때의 화주다"],["화주가 불분명한 경우","대행수입 물품은 수입을 위탁한 자, 대행수입이 아니면 상업서류에 적힌 물품수신인, 수입신고 전에 양도한 물품은 양수인이 납세의무자다"],["우편물","수취인"],["보세운송물품의 도난","보세운송 신고·승인을 받은 자"],["장치물품 폐기","운영인 또는 보관인이 납세의무자이며, 특별납세의무자와 화주가 경합하면 특별납세의무자가 우선한다"]]}],"2":[{"t":"table","title":"가격신고와 잠정가격","head":["구분","내용"],"rows":[["가격신고","납세의무자는 수입신고를 할 때 세관장에게 가격신고를 하고, 통관의 능률을 높이기 위해 필요하면 수입신고 전에 할 수 있다"],["생략 가능","정부·지방자치단체 수입물품, 정부조달물품, 공공기관 수입물품, 관세·내국세등이 부과되지 않는 물품, 수출용 원재료, 특정연구기관 수입물품, 과세가격 미화 1만불 이하 물품 등은 가격신고를 생략할 수 있다"],["생략 불가","1만불 이하라도 개별소비세·주세·교통·에너지·환경세 부과 물품과 분할 수입 물품은 생략하지 못하고, 부과고지 대상 물품과 가산금액이 있는 물품도 생략 대상에서 빠진다"],["잠정가격 신고 사유","거래관행상 가격이 나중에 정해지는 물품, 가산·조정 금액이 나중에 정해질 수 있는 경우, 과세가격 결정방법 사전심사를 신청한 경우 등은 잠정가격으로 신고한다 · 품목분류 사전심사 신청은 사유가 아니다"],["확정가격","2년의 범위에서 세관장이 지정하는 기간 안에 신고하고, 기간 만료 30일 전까지 가산율 산정을 요청할 수 있으며 연장은 지정 신고기간의 만료일부터 2년을 초과하지 못한다"]]},{"t":"cause","title":"거래가격","causes":["우리나라에 수출하기 위하여 판매되는 물품에 구매자가 실제로 지급하였거나 지급하여야 할 가격","더하는 금액: 구매자가 부담하는 수수료·중개료(구매수수료 제외), 용기·포장비, 무료·인하 공급한 물품·용역, 권리사용료, 판매자에게 귀속되는 전매수익, 수입항까지의 운임·보험료","빼는 금액: 수입 후 건설·설치·조립·정비·기술지원 비용, 수입항 도착 후 운임·보험료, 우리나라에서 부과된 관세 등의 세금, 연불이자는 명백히 구분되면 뺀다"],"result":"과세가격은 일정 금액을 더하여 조정한 거래가격이다","effects":["가산은 객관적이고 수량화할 수 있는 자료에 근거해야 하고 자료가 없으면 제31조부터 제35조까지의 방법으로 간다","권리사용료는 해당 물품에 관련되고 해당 물품의 거래조건으로 지급하는 금액이며, 수입물품을 이용해 우리나라에서 고안을 다른 물품에 재현하는 권리의 대가는 제외한다"]},{"t":"vs","title":"판매되는 물품","cols":[{"name":"판매되는 물품이 아닌 것","items":["무상 도착물품","경매 등으로 가격이 정해지는 위탁판매물품","수출자의 책임으로 국내에서 판매하기 위한 물품","지점 등과의 거래 물품","임대차계약 물품","무상 임차 물품","수출자 부담으로 폐기하는 산업쓰레기는 우리나라에 수출하기 위하여 판매되는 물품이 아니다"]},{"name":"판매되는 물품에 들어가는 것","items":["수입자의 책임으로 국내에서 판매하기 위한 물품은 판매되는 물품에 들어간다"]}]},{"t":"table","title":"특수관계와 대체 결정방법","head":["구분","내용"],"rows":[["특수관계","상호 임원·관리자, 법률상 동업자, 고용관계, 특정인이 양쪽의 의결권 있는 주식을 직접·간접으로 5퍼센트 이상 소유·관리, 한쪽이 상대방을 지배, 동일한 제3자의 지배를 받는 경우, 친족관계가 특수관계다"],["특수관계의 거래가격","특수관계가 가격에 영향을 미치면 거래가격을 쓰지 않지만 정상적인 가격결정 관행에 맞거나 비교가격에 근접함을 구매자가 입증하면 거래가격을 인정한다"],["대체 결정방법","거래가격으로 정할 수 없으면 동종·동질물품, 유사물품, 국내판매가격(공제), 산정가격, 합리적 기준의 순서로 결정한다"],["합리적 기준의 제한","합리적 기준에서도 국내생산물품의 국내판매가격, 반드시 높은 가격을 택하는 기준의 가격, 수출국 국내판매가격, 제3국 수출가격, 최저과세기준가격, 자의적 또는 가공적인 가격은 쓰지 못한다"],["신고가격 의심","동일한 공급자로부터 계속 수입하는데 신고가격이 현저하게 변동하면 과세가격으로 인정하기 곤란한 경우로 보아 세관장이 증명자료를 요구할 수 있다"],["통보","세관장은 납세의무자가 서면으로 요청하면 과세가격 결정방법과 산출근거를 서면으로 통보한다 · 장기간 반복 수입물품의 가산율·공제율은 납세의무자의 요청이 있는 경우에 한하여 적용한다"],["사전심사","특수관계자 간 거래물품의 과세가격 결정방법에 의문이 있으면 가격신고 전에 관세청장에게 사전심사를 신청할 수 있다"],["보세공장 혼용","보세공장에서 내국물품과 외국물품을 혼용해 제조한 물품의 과세가격은 제품가격에 외국물품가격이 차지하는 비율을 곱해 계산한다"]]}],"3":[{"t":"table","title":"세율 적용과 탄력관세","head":["구분","내용"],"rows":[["세율 적용 순서","기본세율과 잠정세율은 관세율표에 따르고 잠정세율이 기본세율에 우선한다 · 잠정세율은 대통령령에 따라 적용을 정지하거나 기본세율과의 세율차를 좁히도록 올리거나 내릴 수 있고, 관계부처의 장과 이해관계인은 재정경제부장관에게 그 조치를 요청할 수 있을 뿐 직접 정지하지 못한다 · 덤핑방지·상계·보복·긴급관세 등 탄력관세는 관세율표의 세율보다 먼저 적용한다"],["덤핑방지관세","덤핑방지관세는 정상가격과 덤핑가격의 차액인 덤핑차액에 상당하는 금액 이하로 부과한다 · 무역위원회는 예비조사 결과를 제출한 날의 다음날부터 본조사를 개시하고 3개월 이내에 결과를 제출한다 · 덤핑방지조치와 상계조치는 재정경제부령으로 따로 정하지 않으면 시행일부터 5년이 지나면 효력을 잃는다"],["긴급관세","긴급관세 부과기간은 4년, 잠정긴급관세는 200일을 넘지 못하며 재심사로 연장해도 총 적용기간은 8년을 넘지 못한다 · 부과조치 결정 시행일 이후 수입되는 물품에 한정하여 적용하고 소급하지 않는다 · 긴급관세나 수입수량제한 조치를 결정하면 잠정긴급관세 부과를 중단하고, 재심사로 내용을 바꿔도 최초 조치보다 강화하지 못한다"]]},{"t":"table","title":"조정·할당·계절·국제협력관세","head":["관세","내용"],"rows":[["조정관세","세율 불균형 시정, 공중도덕·생명·건강·환경보전 등, 국내 개발물품 보호, 농림축수산물 시장교란 방지를 위해 100분의 100에서 기본세율을 뺀 율을 더한 범위에서 부과한다"],["할당관세","수입 촉진, 수입가격이 급등한 물품의 국내가격 안정, 유사물품 간 세율 불균형 시정을 위해 100분의 40의 범위의 율을 기본세율에서 뺀다 · 수입을 억제할 때는 일정 수량 초과분에 100분의 40의 범위의 율을 더한다"],["계절관세","국내외 가격차에 상당하는 율의 범위에서 높이거나 100분의 40의 범위의 율을 빼고 부과하며 대상·세율은 재정경제부령으로 정한다"],["국제협력관세","특정 국가와 협상할 때는 기본 관세율의 100분의 50의 범위를 초과하여 양허하지 못한다 · 국내외 가격차에 상당한 율로 양허한 농림축산물의 수입가격이 하락하면 양허세율을 초과하여 부과할 수 있다"]]},{"t":"vs","title":"세율을 정하는 법령","cols":[{"name":"대통령령","items":["보복관세, 조정관세, 편익관세, 할당관세, 국제협력관세, 일반특혜관세의 세율은 대통령령으로 정한다","일반특혜관세는 세율에 차등을 두거나 수입수량을 한정할 수 있고 최빈 개발도상국은 우대할 수 있다"]},{"name":"재정경제부령","items":["덤핑방지관세, 긴급관세, 계절관세, 농림축산물 특별긴급관세의 대상과 세율은 재정경제부령으로 정한다"]}]},{"t":"table","title":"양허·간이세율·품목분류","head":["구분","내용"],"rows":[["양허 철회","양허를 철회하면 철회의 효력이 발생한 날부터 관세법의 세율을 적용하고, 그 보상으로 새로 양허한 품목은 양허 효력이 발생한 날부터 관세법의 세율을 적용하지 않는다"],["편익관세","조약에 따른 편익을 받지 않는 나라의 생산물에 이미 체결된 조약의 편익 한도에서 부여하며 바티칸·모나코·나우루·코모로·시리아 등이 대상이다"],["간이세율","여행자·승무원 휴대품, 수입신고를 하지 않는 우편물, 탁송품, 별송품에 적용하고 관세·임시수입부가세·내국세의 세율을 기초로 대통령령으로 정한다 · 관세가 무세이거나 감면되는 물품, 수출용원재료, 종량세 물품, 상업용 수량 물품, 관세청장이 정하는 고가품에는 적용하지 않는다 · 개별소비세가 과세되는 고급 시계·사행기구도 간이세율 대상이며 모피의류 19%, 신발류 18%, 녹용 21%다"],["관세품목분류위원회","위원장 1명과 30명 이상 40명 이하 위원으로 구성하고, 위원장은 관세청의 3급 또는 고위공무원단 일반직공무원 중 관세청장이 지정한다 · 회의는 위원장과 14명 이상 16명 이하 위원으로 열고 구성원 과반수 출석, 출석위원 과반수 찬성으로 의결한다"],["품목분류 적용기준·사전심사","품목분류 적용기준은 재정경제부장관이 정하고, 사전심사는 신청일부터 30일 이내에 통지하며 통관예정세관장에게도 알린다"]]}],"4":[{"t":"table","title":"관세환급","head":["구분","내용"],"rows":[["환급금 결정·지급","세관장은 환급 청구를 받으면 지체 없이 관세환급금으로 결정하고 30일 이내에 환급하며 세관장이 확인한 환급금은 청구가 없어도 환급한다 · 환급받을 자가 낼 관세·가산세·강제징수비가 있으면 환급금에서 충당할 수 있다 · 환급금에 관한 권리는 제3자에게 양도할 수 있고, 양도 문서에는 양도인·양수인의 주소와 성명, 환급사유, 환급금액을 적는다"],["과다환급·환급가산금","과다환급액을 징수할 때는 과다환급을 한 날의 다음 날부터 징수결정일까지 대통령령으로 정하는 이율로 계산한 금액을 더해야 한다 · 관세환급가산금 이자율은 현행 연 1천분의 31이다"],["환급 사무 절차","세관장은 환급금을 결정하면 즉시 지급지시서를 한국은행에 보내고, 관세환급금결정액보고서는 매월 작성해 재정경제부장관에게 제출한다 · 한국은행은 다음 회계연도 1월 15일까지 지급하지 못한 환급금을 지급미필이월계정에 이월한다 · 환급통지서발행일부터 1년 내에 받지 못하면 다시 환급절차를 요구할 수 있고, 1년 내 지급하지 못한 이월금은 세입에 편입한다"],["자가사용물품 환급","수입신고가 수리된 개인의 자가사용물품을 수입신고 수리일부터 6개월 이내에 보세구역에 반입했다가 수출하거나 세관장 확인을 받고 수출하면 납부한 관세를 환급한다 · 성질·형태가 변하지 않았고 국내에서 사용된 사실이 없다고 세관장이 인정해야 한다 · 전부 수출하면 관세 전액을, 일부 수출하면 그 부분의 관세를 돌려준다"]]},{"t":"table","title":"분할납부","head":["구분","내용"],"rows":[["분할납부 기간","천재지변 등으로 기한까지 납부할 수 없으면 세관장은 1년을 넘지 아니하는 기간으로 분할납부하게 할 수 있다"],["분할납부 승인","시설기계류, 정부·지방자치단체 수입물품, 학교·직업훈련원과 비영리법인 공익사업 물품, 사회복지기관 물품, 중소제조업체 물품 등은 세관장이 5년을 넘지 아니하는 기간으로 승인한다 · 승인 물품은 수입신고 수리일부터 1개월 이내에 설치장소에 반입하고, 연장은 수리일부터 3개월의 범위에서 한다"],["납부자","같은 용도로 쓸 자에게 양도하면 양수인이, 다른 용도로 쓸 자에게 양도하면 양도인이 납부한다 · 파산선고를 받으면 파산관재인, 법인이 해산하면 청산인이 납부하고, 합병·분할 후 법인은 연대하여 납부한다"],["즉시징수","용도 외 사용·양도, 기한 내 미납, 파산선고, 법인 해산이면 미납 관세 전액을 즉시 징수하며 법인 분할은 즉시징수 사유가 아니다"]]},{"t":"table","title":"면세","head":["구분","내용"],"rows":[["외교관용 면세","외국 대사관·공사관·영사관의 업무용품, 대사·공사와 그 가족의 물품, 파견 고문관의 물품, 외국계약자의 업무용품은 면세한다"],["명예총영사·외국계약자 가족","명예총영사의 물품과 외국계약자 가족의 물품은 면세하지 않는다"],["정부용품·소액물품 면세","재외공관에서 반환된 공용품은 정부용품 면세이고, 훈장·기록문서·상품목록, 미화 250달러 이하 상용견품, 물품가격 미화 150달러 이하 자가사용 소액물품은 소액물품 면세다"],["여행자 휴대품 면세","기본면세범위는 여행자 1명당 과세가격 합계 미화 800달러 이하다 · 술은 2리터 이하이면서 미화 400달러 이하, 궐련 200개비, 엽궐련 50개비, 니코틴용액 20밀리리터, 향수 100밀리리터까지 따로 면제한다 · 19세 미만이 반입하는 술·담배는 면제하지 않고, 별송품은 입국한 날부터 6월 이내에 도착해야 한다"]]},{"t":"table","title":"재수출","head":["구분","내용"],"rows":[["재수출면세","물품은 수입신고 수리일부터 1년의 범위에서 세관장이 정한 기간에 수출해야 하며 기간 내 수출하지 않으면 500만원을 넘지 않는 범위에서 관세의 100분의 20을 가산세로 징수한다"],["재수출감면","내용연수 5년 이상, 관세액 500만원 이상 물품이 대상이며 경감률은 6개월 이내 100분의 85, 1년 이내 70, 2년 이내 55, 3년 이내 40, 4년 이내 30이다"],["사후관리기간","감면물품 사후관리기간은 세율에 감면율을 곱한 율이 3퍼센트 이하면 1년, 7퍼센트 이하면 2년 이내다"]]}],"5":[{"t":"table","title":"납부와 정정","head":["구분","내용"],"rows":[["납부기한","납세신고를 하면 납세신고 수리일부터, 납부고지를 하면 고지를 받은 날부터, 즉시반출신고를 하면 수입신고일부터 각각 15일 이내에 납부하고, 수리 전에도 납부할 수 있다"],["월별납부","세관장은 성실납세자에게 납부기한이 같은 달에 속하는 세액을 그 달의 말일까지 한꺼번에 내게 할 수 있고 승인 유효기간은 2년이다"],["세액심사","수리 후가 원칙이고, 감면·분할납부 물품, 체납자의 신고물품(10만원 미만 또는 체납기간 7일 이내 제외), 불성실신고인의 물품은 수리 전에 심사한다"],["보정·수정신고","부족세액이나 과세가격·품목분류 오류를 알면 신고납부한 날부터 6개월 이내에 보정을 신청할 수 있고, 보정신청을 한 날의 다음 날까지 납부한다 · 보정기간이 지나면 제척기간이 끝나기 전까지 수정신고를 할 수 있고 수정신고한 날의 다음 날까지 납부한다"],["경정청구","과다 납부는 최초 납세신고일부터 5년 이내에 경정청구하며 세관장은 2개월 이내에 결과를 통지하고 통지가 없으면 그 다음 날부터 불복할 수 있다"],["부과고지·최저한","납부할 세액이 1만원 미만이면 징수하지 않고 수입신고수리일을 납부일로 본다"],["가산세","미납·부족세액에는 부족세액의 100분의 10과 일수에 따른 납부지연가산세, 고지 후 기한까지 미납한 세액의 100분의 3을 더하며 부정행위 과소신고는 100분의 60이다 · 체납액이 150만원 미만이면 일수에 따른 부분을 붙이지 않는다"]]},{"t":"table","title":"제척기간과 소멸시효","head":["구분","내용"],"rows":[["부과제척기간","부과할 수 있는 날부터 5년, 무신고 수입은 7년, 부정한 방법의 포탈·환급·감면은 10년이다"],["제척기간 기산일","수입신고한 날의 다음날이고, 감면 관세 징수는 사유가 발생한 날, 과다·부정환급은 환급한 날의 다음날이다 · 불복 결정·판결이 있으면 확정된 날부터 1년까지 경정할 수 있고, 제척기간은 중단되지 않는다"],["소멸시효","관세징수권은 5억원 이상(내국세 포함)이면 10년, 그 밖에는 5년, 환급청구권은 5년간 행사하지 않으면 시효가 완성된다"],["시효 기산","신고납부 관세는 수입신고 수리일부터 15일이 지난 날의 다음 날, 부과고지 관세는 납부고지를 받은 날부터 15일이 지난 날의 다음 날부터 기산한다 · 착오·이중납부 환급은 납부일, 법률 개정에 따른 환급은 그 법률의 시행일, 경정에 따른 환급은 경정결정일부터 기산한다"],["시효의 중단","관세징수권 소멸시효는 납부고지, 경정처분, 납부독촉, 통고처분, 고발, 특정범죄가중법 제16조의 공소제기, 교부청구, 압류로 중단된다 · 가압류와 사해행위취소소송 제기는 중단 사유가 아니다"],["시효의 정지","분할납부기간, 징수유예기간, 압류·매각의 유예기간, 사해행위 취소소송기간에는 시효가 진행하지 않고, 그 소송이 각하·기각·취하되면 정지 효력이 없다"]]},{"t":"table","title":"납세담보","head":["구분","내용"],"rows":[["담보의 종류","금전, 국채·지방채, 세관장이 인정하는 유가증권, 납세보증보험증권, 토지, 보험에 가입된 등기·등록 건물·선박 등, 세관장이 인정하는 보증인의 납세보증서다"],["충당·평가","보증보험증권·납세보증서는 세관장 요청 시 언제든지 지급한다는 내용이어야 하고, 충당할 때는 매각하지 않고 보증인에게 납부를 통보한다 · 토지·건물은 상속세 및 증여세법 제61조를 준용해 평가하고, 관세가 확정되지 않은 경우 담보 금액은 관세청장이 정한다"],["담보 제공 기한","담보액 확정일부터 10일 이내에 담보를 내지 않으면 세관장이 납부고지를 할 수 있고, 매각예정일 1일 전까지 납부하면 매각을 중지한다"],["건물 담보·포괄담보","보험에 든 건물을 담보로 할 때 보험기간은 담보 필요기간에 30일 이상을 더한다 · 납세의무자와 관세 납부를 보증한 자는 포괄담보를 미리 제공할 수 있고 그 요건은 관세청장이 정한다"]]},{"t":"table","title":"체납 제재","head":["제재","내용"],"rows":[["명단 공개","체납발생일부터 1년이 지난 체납관세등이 2억원 이상이면 관세청장이 명단을 공개할 수 있으나 불복청구가 진행 중이면 공개하지 않는다"],["감치","3회 이상 체납, 각 1년 경과, 합계 2억원 이상이고 납부능력이 있는데 체납하면 법원이 30일의 범위에서 감치할 수 있으며 내국세등도 포함하고 즉시항고가 가능하다"],["사업정지·허가취소","허가사업자가 3회 이상, 합계 500만원 이상 체납하면 세관장은 사업정지·허가취소를 요구할 수 있다"]]}],"6":[{"t":"table","title":"관세조사","head":["구분","내용"],"rows":[["납세자권리헌장","세관공무원은 관세범 조사, 세액 결정·경정을 위한 방문·서면조사, 압류, 보세판매장 조사를 할 때 납세자권리헌장을 내준다 · 긴급 체포·압수·수색이나 현행범 도주 우려처럼 조사목적을 달성할 수 없으면 내주지 않을 수 있다"],["성실성 추정","납세자는 성실하다고 추정하되, 납세협력의무 불이행, 탈루·오류 혐의의 명백한 자료, 구체적인 탈세제보가 있으면 추정이 배제된다"],["조사 원칙·대상","관세조사는 필요한 최소한의 범위에서 하고 통합조사가 원칙이며, 특정 분야만 조사할 필요가 있거나 조세채권 확보를 위해 긴급한 경우는 예외다 · 정기선정 조사는 신고성실도 분석과 무작위추출방식 표본조사로 대상을 고른다 · 경제질서 교란 탈세혐의자 일제조사는 이미 조사받은 자도 다시 조사할 수 있다"],["조사 절차","조사 시작 20일 전에 사전통지하고, 범칙사건이나 증거인멸 우려가 있으면 생략한다 · 납세자는 변호사·관세사를 조사에 참여시킬 수 있고, 장부를 일시 보관할 때는 동의서를 받고 보관증을 내준다 · 조사 결과는 종료 후 20일 이내에 서면으로 통지하며 납세자가 폐업한 경우에는 통지하지 않을 수 있다"]]},{"t":"flow","title":"과세전통지","steps":["세관장은 부족세액을 징수하려면 미리 서면으로 통지한다","통지하려는 날부터 3개월 이내에 제척기간이 만료되는 경우, 확정가격 신고, 수리 전 세액심사 결과 징수, 재수출면세 관세 징수, 관세포탈죄 고발, 감사원 시정요구, 명백한 계산착오는 통지를 생략한다","통지를 받으면 30일 이내에 과세전적부심사를 청구","세관장·관세청장은 30일 이내에 결정"]},{"t":"table","title":"불복","head":["구분","내용"],"rows":[["불복 대상","위법 또는 부당한 처분, 필요한 처분을 받지 못한 경우가 불복 대상이고 통고처분, 감사원 심사청구 처분, 과태료 부과처분은 제외된다"],["불복 경로","이의신청은 처분 세관장에게, 심사청구는 세관장을 거쳐 관세청장에게, 심판청구는 조세심판원에 한다 · 동일한 처분에 심사청구와 심판청구를 중복하여 제기할 수 없고, 불복해도 처분의 집행은 원칙적으로 정지되지 않는다"],["청구기간·결정","심사청구는 처분을 한 것을 안 날부터 90일 이내, 이의신청을 거쳤으면 결정을 통지받은 날부터 90일 이내에 한다 · 심판청구 후(같은 날 포함) 낸 심사청구나 기간이 지난 청구는 각하하고, 이유 없으면 기각한다 · 보정 요구 기간은 20일 이내이고 보정기간은 결정기간에 넣지 않는다"],["세관장 의견서","심사청구서를 받은 세관장은 7일 내에 의견서를 붙여 관세청장에게 보내고, 관세청장은 지체 없이 부본을 청구인에게 보낸다"],["관세심사위원회","관세청장은 관세심사위원회의 의결에 따라 결정하고, 위원회 회의는 공개하지 않는 것이 원칙이며, 의결이 명백히 위법하면 한 차례 재심의를 요청할 수 있다 · 결정 통지를 게시판에 공고하면 10일이 지난 날에 통지받은 것으로 본다"]]},{"t":"table","title":"대리인과 납세자보호","head":["구분","내용"],"rows":[["대리인","이의신청·심사청구·심판청구의 대리인은 변호사 또는 관세사이고 세무사는 들어가지 않는다 · 청구 대상이 3천만원 미만이면 배우자, 4촌 이내의 혈족, 배우자의 4촌 이내의 혈족도 대리인이 될 수 있다"],["대리인의 권한","대리인의 권한은 서면으로 증명하고, 청구의 취하는 특별한 위임이 있어야 하며 해임은 서면으로 재결청에 신고한다"],["납세자보호위원회","본부세관 납세자보호위원회는 납세자보호담당관 1명과 해당 세관장이 위촉하는 17명 이내의 민간위원으로 구성한다"],["과세정보","은행이 급부·지원 대상자 심사용 과세정보를 요구할 때는 당사자의 동의를 받아야 제공할 수 있다 · 체납액이 5천만원 미만이 되면 관세청장은 즉시 출국금지 해제를 요청한다"]]}],"7":[{"t":"table","title":"국제항과 입출항","head":["구분","내용"],"rows":[["국제항","항구는 5천톤급 이상 국제무역선이 연간 50회 이상 입항하거나 입항이 예상되어야 지정된다 · 국제무역선·국제무역기는 국제항에 한정하여 운항하고, 국제항이 아닌 곳은 출입허가를 받는다 · 출입허가수수료는 1만원에 미달하면 1만원으로 하고 총액은 50만원을 넘지 못하며 유조선 청소작업 등을 위한 입항은 면제한다"],["입항","입항은 세관장에게 입항보고를 하는 것이고 허가 사항이 아니다"],["출항","출항하려면 출항하기 전에 세관장의 출항허가를 받고 적재화물목록을 제출하되, 세관장이 정하면 출항허가 후 7일의 범위에서 낼 수 있다 · 승객예약자료는 관세청장이 지정하는 세관공무원만 열람하고, 출항 선박·항공기는 출항 후 3시간 이내, 입항 시는 입항 1시간 전까지(운항시간이 짧으면 30분 전) 제출한다"],["하역","국제무역선에 물품을 하역하려면 세관장에게 신고하고, 국제무역선에 내국물품을 싣거나 국내운항선에 외국물품을 실을 때는 세관장의 허가를 받는다 · 국제항 바깥에서 하역·환적하려면 선장이 세관장의 허가를 받으며 세관장은 10일 이내에 허가 여부를 통지하고 수수료는 하역 1일마다 4만원이다 · 선박용품·항공기용품과 선내판매용품을 하역·환적할 때도 세관장의 허가를 받는다"],["국경출입차량","국경출입차량은 관세통로를 경유하고 통관역이나 통관장에 정차한다 · 통관역은 국경에 근접한 철도역 중에서 관세청장이 지정하고, 통관장과 관세통로는 세관장이 지정한다 · 관세통로는 육상국경에서 통관역에 이르는 철도와 통관장에 이르는 육로·수로다"]]},{"t":"table","title":"보세구역","head":["구분","내용"],"rows":[["보세구역 구분","보세구역은 지정보세구역·특허보세구역·종합보세구역으로 나뉜다"],["지정보세구역","지정장치장과 세관검사장이고 세관장이 지정한다 · 세관장은 반입 물품의 종류를 제한할 수 있고, 관세청장이 정하는 보세구역에 반입되어 수입신고가 수리된 물품은 수리일부터 15일 이내에 반출한다"],["화물관리인","세관장이 관리하지 않는 시설은 소유자·관리자와 협의해 화물관리인을 지정하고, 지정할 수 없으면 세관장이 직접 관리할 수 있다 · 화물관리인이 스스로 지정 취소를 요청한 경우에는 청문하지 않는다"],["보수작업","현상 유지나 성질을 변하지 않게 하는 범위에서 세관장의 승인을 받아 하고, 외국물품은 수입될 물품의 보수작업 재료로 쓸 수 없다"]]},{"t":"table","title":"특허보세구역 운영","head":["구분","내용"],"rows":[["특허기간·수수료","보세전시장·보세건설장을 뺀 특허보세구역의 특허기간은 10년 이내이고 특허신청 수수료는 4만5천원이다 · 특허수수료는 연면적 기준 분기당 금액이며 보세공장과 목재만 장치하는 수면 보세창고는 4분의 1이다"],["보세판매장 특허수수료","매출액 기준(2천억원 이하 1만분의 5, 1조원 이하 1억원에 초과분 1만분의 25, 1조원 초과 21억원에 초과분 1천분의 5)이고 다음 연도 4월 30일까지 낸다"],["반입정지","자금능력 부족, 법령·명령 위반, 시설 미비, 1년 동안 반입·반출 실적이 없는 경우 등에는 6개월의 범위에서 물품반입을 정지할 수 있다"],["특허취소","거짓 특허, 결격사유, 명의대여는 특허를 반드시 취소하고, 1년 이내 3회 이상 정지처분과 2년 이상 반입실적 없음은 취소할 수 있다"],["과징금","정지 대신 매출액의 100분의 3 이하 과징금을 부과할 수 있고 납부통지일부터 20일 이내에 낸다"]]},{"t":"flow","title":"장치기간경과물품 매각","steps":["살아 있는 동식물, 부패 우려 물품, 다른 물품에 해를 끼칠 우려가 있는 물품, 상품가치가 떨어질 물품은 장치기간 전에도 공고 후 매각한다","매각 시작 10일 전에 공고","경쟁입찰에서 팔리지 않으면 5일 이상 간격을 두어 다시 입찰","질권자·유치권자는 물품을 매수인에게 인도하고 매각한 날부터 1개월 이내에 권리 증명 서류를 낸다"]}],"8":[{"t":"table","title":"보세운송","head":["구분","내용"],"rows":[["신고","외국물품은 국제항, 보세구역, 허가된 장소, 세관관서, 통관역, 통관장, 통관우체국 사이에서만 그대로 운송할 수 있고 세관장에게 신고한다 · 신고인은 화주, 관세사등, 보세운송업자다"],["승인","재보세운송 물품, 귀금속·한약재처럼 부피가 작고 고가인 물품, 화주가 직접 운송하는 물품, 세관장이 지정한 물품, 최초 보세구역 반입일부터 30일이 지난 물품은 세관장의 승인을 받는다"],["관리","수출신고가 수리된 물품은 관세청장이 따로 정하는 것 외에는 보세운송절차를 생략한다 · 세관장은 보세운송 물품에 관세 담보를 제공하게 할 수 있고 운송통로를 제한할 수 있다 · 보세운송은 관세청장이 정하는 기간 내에 끝내야 하고, 내국물품을 국제무역선·국제무역기로 운송하려면 세관장에게 내국운송 신고를 한다"]]},{"t":"table","title":"보세운송업자등","head":["구분","내용"],"rows":[["등록 대상","보세운송업자, 화물운송주선업자, 국제무역선·기에 하역하거나 용품·선내판매물품을 공급하는 자, 국제항 보세구역에서 물품·용역을 제공하는 자, 상업서류·견본품 송달업자는 등록해야 한다"],["등록 유효기간","등록 유효기간은 3년이고 갱신은 기간만료 1개월 전까지 신청한다 · 폐업, 법인 해산·개인 사망, 유효기간 만료, 등록 취소로 효력이 상실된다"],["제재","명령 위반 시 6개월의 범위에서 업무정지하거나 매출액의 100분의 3 이하 과징금을 부과한다"],["과징금 가감","보세운송업자등에 대한 과징금은 산정 금액의 4분의 1 범위에서 사업규모·위반정도·위반횟수를 고려해 가중하거나 감경한다 · 가중하더라도 총액은 연간매출액의 100분의 3을 넘지 못한다"]]},{"t":"table","title":"보세공장과 보세건설장","head":["구분","내용"],"rows":[["보세공장","보세공장에서는 외국물품이나 외국물품과 내국물품을 원료로 제조·가공하고, 내국물품만을 원료로 하려면 세관장의 허가를 받는다"],["보세공장 외 작업","허가는 신청일부터 10일 이내에 통지하고, 작업완료 결과는 허가기간이 끝나는 날부터 10일 이내에 통보한다"],["제외 업종","국내외 가격차 상당 율로 양허한 농·임·축산물을 원료로 하는 업종과 국민보건·환경보전에 지장을 주는 업종은 수입물품 제조용 보세공장에서 제외된다"],["보세건설장","운영인은 반입한 외국물품을 사용하기 전에 수입신고를 하고 세관공무원의 검사를 받는다 · 특허보세구역 운영인이 장치물품이나 작업 원재료를 바꾸려면 세관장의 승인을 받는다"]]},{"t":"table","title":"종합보세구역","head":["구분","내용"],"rows":[["지정·운영","종합보세구역은 관세청장이 지정하고, 직권 지정 시 관계 중앙행정기관의 장이나 지방자치단체의 장과 협의하며 물량 감소로 존속 필요가 없으면 관세청장이 지정을 취소한다 · 종합보세기능을 하려는 자는 세관장에게 설치·운영 신고를 하고, 외국물품 반출입도 세관장에게 신고한다 · 관세청장은 판매 물품의 종류와 수량을 제한할 수 있다"],["종합보세사업장 제재","설비 유지의무 위반, 물량 감소, 1년 동안 외국물품 반출입 실적이 없으면 6개월의 범위에서 종합보세기능 수행을 중지시킨다 · 거짓 신고, 결격사유, 명의 대여는 사업장 폐쇄를 명한다"],["물품관리","시설기계류와 연료·윤활유·사무용품은 수입통관 후 사용하고, 허가받아 내국물품만 원료로 쓰는 경우의 원료는 반출입 신고를 생략하지 못한다 · 외국인관광객이 구매한 날부터 3개월 이내에 국외 반출이 확인되면 판매인이 관세를 환급받는다"]]}],"9":[{"t":"table","title":"원산지","head":["구분","내용"],"rows":[["결정기준","2개국 이상에 걸쳐 생산된 물품은 본질적 특성을 부여하기에 충분한 실질적 생산·가공이 최종적으로 수행된 나라가 원산지이고, 6단위 품목번호가 바뀐 물품을 최종 생산한 국가로 본다 · 포장개선·상표표시 같은 개수작업, 재포장, 단순 조립, 가축 도축, 보존 작업을 한 나라는 원산지로 인정하지 않는다 · 원산지가 아닌 국가를 경유하지 않고 직접 운송·반입되어야 그 원산지가 인정된다"],["특수 물품","자국 선박이 채집·포획한 어획물은 그 국가, 촬영된 영화용 필름은 제작자가 속하는 국가가 원산지다 · 기계와 함께 수입·판매되는 통상 수량의 부속품·예비부분품·공구는 그 기계의 원산지를 따른다 · 포장용품은 내용물품의 원산지를 따르지만 품목분류표상 별개의 품목번호이면 따로 정한다"],["원산지증명서","원산지 확인이 필요한 물품의 수입자가 원산지증명서를 내지 않으면 일반특혜·국제협력·편익관세를 적용하지 않을 수 있다 · 원산지증명서는 제출일부터 소급하여 1년 이내에 발행된 것이어야 하고, 과세가격 15만원 이하 물품은 제출하지 않아도 된다 · 세관장은 수입신고 수리 이후에 발급국 세관에 진위 확인을 요청할 수 있고, 회신이 없거나 필요한 정보가 빠지면 특혜를 적용하지 않을 수 있다"]]},{"t":"table","title":"수출입신고","head":["구분","내용"],"rows":[["신고","수출·수입·반송하려면 품명·규격·수량·가격 등을 세관장에게 신고한다 · 휴대품·탁송품·별송품, 우편물, 면세 물품, 무세 국제운송용 컨테이너는 신고를 생략하거나 간소하게 할 수 있으나 최초 수입하는 운송수단은 제외한다"],["신고기한과 가산세","지정장치장·보세창고 반입일부터 30일 이내에 신고하지 않으면 경과일수에 따라 과세가격의 1천분의 5(20일 내), 10(50일 내), 15(80일 내), 20을 가산세로 징수하고 상한은 500만원이다"],["입항전신고","입항전수입신고는 선박은 입항 5일 전, 항공기는 1일 전부터 할 수 있고 신고된 물품은 우리나라에 도착한 것으로 본다"],["즉시반출","즉시반출신고를 하면 10일 이내에 수입신고를 해야 하고 어기면 관세의 100분의 20을 가산세로 징수한다"],["수리전반출","담보를 제공하고 세관장의 승인을 받으며 국가·지방자치단체, 지방공사·공단, 최근 2년간 위반이 없는 신용우수자 등은 담보를 생략할 수 있다"],["각하·취하·검사","요건을 갖추지 못했거나 부정한 방법으로 한 신고는 각하할 수 있고 즉시 통지서를 보낸다 · 수입·반송신고는 장치장소에서 반출한 뒤에는 취하할 수 없고, 수리 후 취하를 승인하면 수리의 효력이 상실된다 · 적법한 물품검사로 손실이 나면 관세청장 또는 세관장이 보상하며 수리할 수 없으면 과세가격 상당액을 보상한다"]]},{"t":"table","title":"신고서류 보관기간","head":["서류","보관기간"],"rows":[["수입신고필증, 수입거래 계약서, 수입물품 가격결정 자료","수리일부터 5년 보관한다"],["수출신고필증, 반송신고필증, 수출·반송물품 가격결정 자료","3년이다"],["보세화물 반출입 자료, 적재화물목록 자료, 보세운송 자료","2년이다"]]},{"t":"table","title":"통관 제한과 우편물","head":["구분","내용"],"rows":[["통관 제한","원산지를 사실과 다르게 표시하거나 기준에 맞지 않게 표시한 물품, 품질등을 오인하게 표시한 물품은 통관을 허용하지 않는다 · 환적 중 원산지를 우리나라로 허위 표시한 물품은 유치할 수 있고 화주에게 통지한다"],["지식재산권","보호대상은 특허권, 실용신안권, 디자인권, 상표권, 저작권·저작인접권, 식물신품종 보호법상 품종보호권, 지리적표시권이며, 통관 보류 요청서에는 품명·수출입자·수출입국, 권리의 내용·범위, 요청사유, 침해 입증 사항을 적는다"],["우편물 통관","우편물은 통관우체국을 경유하고 통관우체국은 체신관서 중에서 관세청장이 지정한다 · 수출입 제한·금지 물품, 세관장 확인 물품, 관세청장 기준에 해당하는 판매 목적 물품, 가공무역용 무상 물품, 의약품·건강기능식품 등은 수취인·발송인이 신고한다 · 세관장은 결정사항을 통관우체국의 장에게 통지하고, 관세를 징수하기 전에는 우편물을 내줄 수 없으며 우편물이 반송되면 납세의무는 소멸한다"]]}],"10":[{"t":"table","title":"세관공무원의 권한과 자료","head":["구분","내용"],"rows":[["권한","관세청장이나 세관장은 명령 집행에 필요하면 운송수단의 출발을 중지시키거나 진행을 정지시키고, 서류 제출·보고를 명할 수 있다 · 세관공무원은 관계자에게 질문하고 장부·물품을 조사하며 물품·운송수단·장치장소를 검사하거나 봉쇄할 수 있다 · 명예세관원은 관세청장이 위촉하고 필요하면 활동경비를 지급할 수 있다"],["자료 비치 영업장","외국 생산물품의 수입사실 증명자료를 갖춰야 하는 상설영업장은 백화점, 최근 1년간 수입물품 매출액 5억원 이상인 수입물품 전문·할인판매점, 최근 1년간 수입물품 매출액 10억원 이상인 통신판매자, 수입물품 매출이 전체의 30퍼센트를 초과하는 영업장, 최근 3년 이내 관세법 위반 처벌 전력이 있는 영업장이다"],["과세자료 제출","관세청장은 국가기관·지방자치단체 등 과세자료제출기관에 자료를 요청할 수 있고, 지방자치단체조합, 지방공사·공단, 신용카드업자, 여신전문금융업협회도 제출기관이다 · 추가·보완 요구를 받으면 요구를 받은 날부터 15일 이내에 따르고, 여권발급 자료는 실시간으로 낸다 · 과세자료 비밀유지의무를 위반하면 3년 이하의 징역 또는 1천만원 이하의 벌금이며 징역과 벌금을 병과할 수 있다"]]},{"t":"table","title":"관세 벌칙","head":["죄","처벌"],"rows":[["수출입 금지물품","수출입 금지물품을 수출입하면 7년 이하의 징역 또는 7천만원 이하의 벌금이다"],["밀수입","신고 없이 수입하거나 다른 물품으로 신고해 수입하면 5년 이하의 징역 또는 관세액의 10배와 물품원가 중 높은 금액 이하의 벌금이다"],["밀수출·반송","신고 없이 수출·반송하거나 다른 물품으로 신고해 수출·반송하면 3년 이하의 징역 또는 물품원가 이하의 벌금이다"],["관세포탈죄","과세가격·관세율을 거짓 신고하거나 수입제한 회피를 위해 부분품으로 분할 수입하면 3년 이하의 징역 또는 포탈 관세액의 5배와 물품원가 중 높은 금액 이하의 벌금이며, 구매대행업자도 처벌된다 · 부정한 감면·징수면탈·환급은 3년 이하의 징역 또는 해당 세액의 5배 이하 벌금이다"],["가격조작죄","2년 이하의 징역 또는 5천만원, 물품원가, 가격 차액 중 가장 높은 금액 이하의 벌금이다"],["교사·미수·예비","밀수출입죄와 관세포탈죄는 교사·방조를 정범에 준하여 처벌한다 · 전자문서 위조·변조죄, 밀수출입죄, 관세포탈죄의 미수범은 본죄에 준하고, 예비는 본죄의 2분의 1을 감경하여 처벌한다"],["병과","징역과 벌금의 병과는 밀수출입죄부터 미수범 등까지와 밀수품 취득죄에 적용되고 가격조작죄 미수와 강제징수 면탈죄는 병과 대상이 아니다"]]},{"t":"table","title":"관세범 조사","head":["구분","내용"],"rows":[["조사·고발","관세범의 조사·처분은 세관공무원이 하고, 관세청장이나 세관장의 고발이 없으면 검사는 공소를 제기할 수 없다"],["야간 조사·신변수색","해 진 후에는 검증·수색·압수를 새로 시작하지 못하지만 이미 시작한 것은 계속할 수 있다 · 신변수색은 증거물품 은닉이 인정되어 제시를 요구했는데 따르지 않을 때 하고, 여성의 신변은 성년의 여성을 참여시킨다"],["서류 송달","관세범에 관한 서류는 인편이나 등기우편으로 송달한다 · 본인이 서명할 수 없으면 다른 사람이 대리서명할 수 있다"],["현행범인","현행범인에 대한 조사로서 긴급하면 주요 내용을 적은 서면으로 조서를 대신할 수 있고, 현행범인은 누구든지 체포할 수 있다"]]},{"t":"table","title":"통고처분과 과태료","head":["구분","내용"],"rows":[["통고처분","벌금 상당액, 몰수 해당 물품, 추징금 상당액을 납부하게 하는 것이고 과징금은 들어가지 않는다"],["벌금 상당액","벌금 최고액의 100분의 30이며, 조사 방해 등은 100분의 50 범위에서 늘리고 자진납부·자수 등은 100분의 50 범위에서 줄인다"],["과태료","세관공무원에게 금품을 공여한 자는 금품 상당액의 2배 이상 5배 내의 과태료를 낸다"]]}],"11":[{"t":"table","title":"협정관세","head":["구분","내용"],"rows":[["FTA 관세특례법의 지위","FTA 관세특례법은 관세법에 우선하고 정하지 않은 사항은 관세법을 따르며, 특례법이나 관세법이 협정과 상충하면 협정을 우선 적용한다"],["정의","체약상대국에는 국가연합·경제공동체·독립된 관세영역이 포함된다 · 협정관세는 관세를 철폐하거나 세율을 연차적으로 인하하여 부과하는 관세다"],["세율과 우선순위","협정관세의 연도별 세율, 적용기간, 적용수량은 협정에 따라 대통령령으로 정한다 · 협정관세 세율이 관세법 제50조의 적용세율과 같거나 높으면 관세법 세율을 우선하되, 같을 때 수입자가 신청하면 협정관세를 적용할 수 있다 · 덤핑방지·상계·보복·긴급관세 등의 세율은 협정관세보다 우선한다"],["적용신청","수리 전까지 신청하지 못했으면 수입신고 수리일부터 1년 이내에 사후적용을 신청할 수 있다 · 품목분류 변경으로 수정신고한 경우에는 수정신고를 한 날부터 45일 이내에 신청한다 · 미화 1천달러 이하 물품은 증빙서류 제출을 면제하지만 분할 수입 등 부정한 방법으로 1천달러 이하로 맞춘 물품은 제출을 요구할 수 있다"],["원산지 결정","물품 전부를 생산한 국가가 원산지다 · 둘 이상의 국가에 걸쳐 생산되면 품목번호가 일정 단위 이상 바뀐 최종 가공국, 일정 수준 이상의 부가가치를 창출한 국가, 주요 공정을 수행한 국가를 협정에 따라 원산지로 한다 · 원산지가 아닌 국가에서 선적되면 원산지로 인정하지 않지만 그 국가의 보세구역에서 운송 목적으로 환적·일시 보관된 경우는 인정한다"]]},{"t":"table","title":"원산지증명서 유효기간","head":["국가","유효기간"],"rows":[["발급 방식","원산지증명서는 영문으로 작성하고 지정된 서명권자가 서명하여 발급하며 유효기간은 원칙적으로 발급일 또는 서명일부터 1년이다"],["미합중국","서명일부터 4년"],["칠레·캐나다·뉴질랜드","서명일부터 2년"],["호주","발급일 또는 서명일부터 2년"],["이스라엘","12개월"],["페루","1년이되 비당사국에서 일시 보관되면 2년이다"]]},{"t":"table","title":"원산지 증빙과 인증수출자","head":["구분","내용"],"rows":[["증빙서류 보관","수입자·수출자·생산자는 원산지증빙서류를 5년의 범위에서 대통령령으로 정하는 기간 보관한다 · 생산자는 원가계산서·원재료내역서·공정명세서를, 수출자는 구입 증빙서류와 출납·재고관리대장을 보관한다 · 원산지 내용의 오류를 알면 30일 이내에 세관장과 상대국 수입자에게 통보한다"],["원산지인증수출자","품목번호 6단위 기준으로 원산지 충족을 증명할 능력이 있고, 최근 2년간 조사 거부, 서류 보관의무 위반, 부정 발급 사실이 없어야 하며 원산지관리전담자를 둔다"],["사전심사","원산지, 품목분류·가격·원가결정, 환급·감면, 원산지 표시에 대해 신청하고, 사전심사서 변경은 관세청장이 한다"],["조사결과 통지","원산지 조사결과 통지는 유럽연합·영국·튀르키예가 조사 요청일부터 10개월, 콜롬비아가 150일, 중미 공화국들이 접수 다음 날부터 150일이다"]]},{"t":"table","title":"가산세·벌칙과 환급특례","head":["구분","내용"],"rows":[["가산세","협정관세 적용 후 부족세액에는 100분의 10, 원산지증명서 위조·변조 등 부정행위면 100분의 60의 가산세를 매긴다"],["벌칙","비밀취급자료 누설은 3년 이하의 징역 또는 3천만원 이하의 벌금이다 · 원산지증빙서류 부정 발급, 서류 미보관, 사전심사 자료 허위 제출은 2천만원 이하의 벌금이고, 과실로 사실과 다르게 발급받으면 300만원 이하의 벌금이다"],["수출용원재료 환급특례법","세관장은 물품이 수출등에 제공되면 그 날부터 소급하여 2년 이내에 수입된 수출용원재료의 관세등을 환급한다 · 환급신청은 수출등에 제공된 날부터 5년 이내에 관세청장이 지정한 세관에 한다 · 환급금은 소요량계산서에 따라 산출하고, 과다환급금을 징수할 때는 환급한 날의 다음 날부터 징수결정일까지의 이자를 더한다"]]}]};
